CustomField.formula:
IMAGE("http://chart.googleapis.com/chart?chf=bg,lg,0,F2F2F2,0,CECECE,1&chs=350x175&cht=p3&chco=FF0000|FFFF88|80C65A&chd=t:"& 
TEXT( Current_Year_Red_Revenue__c )&","& 
TEXT( Current_Year_Yellow_Revenue__c)&","& 
TEXT( Current_Year_Green_Revenue__c )&"&chds=a&chdl=Red|Yellow|Green&chdlp=t&chl="&"$"& 
IF(Current_Year_Red_Revenue__c < 1000, TEXT(FLOOR(Current_Year_Red_Revenue__c)),
  IF(Current_Year_Red_Revenue__c < 1000000, TEXT(FLOOR(Current_Year_Red_Revenue__c/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Red_Revenue__c)), 3),
    IF(Current_Year_Red_Revenue__c < 1000000000, TEXT(FLOOR(Current_Year_Red_Revenue__c/1000000)) & ',' & TEXT(FLOOR(MOD(Current_Year_Red_Revenue__c,1000000)/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Red_Revenue__c)), 3), "E")
  )
)&"|"&"$"& 
IF(Current_Year_Yellow_Revenue__c < 1000, TEXT(FLOOR(Current_Year_Yellow_Revenue__c)),
  IF(Current_Year_Yellow_Revenue__c < 1000000, TEXT(FLOOR(Current_Year_Yellow_Revenue__c/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Yellow_Revenue__c)), 3),
    IF(Current_Year_Yellow_Revenue__c < 1000000000, TEXT(FLOOR(Current_Year_Yellow_Revenue__c/1000000)) & ',' & TEXT(FLOOR(MOD(Current_Year_Yellow_Revenue__c,1000000)/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Yellow_Revenue__c)), 3), "E")
  )
)&"|"&"$"& 
IF(Current_Year_Green_Revenue__c < 1000, TEXT(FLOOR(Current_Year_Green_Revenue__c)),
  IF(Current_Year_Green_Revenue__c < 1000000, TEXT(FLOOR(Current_Year_Green_Revenue__c/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Green_Revenue__c)), 3),
    IF(Current_Year_Green_Revenue__c < 1000000000, TEXT(FLOOR(Current_Year_Green_Revenue__c/1000000)) & ',' & TEXT(FLOOR(MOD(Current_Year_Green_Revenue__c,1000000)/1000)) & ',' & RIGHT(TEXT(FLOOR(Current_Year_Green_Revenue__c)), 3), "")
  )
)
&"&chma=45,2,0,2&chtt=&chts=676767,12.933", "No Image",175,350)
